#!/usr/bin/env python3
"""Claude Code hook for imitation-landing-approach.

PreToolUse (default): block edits that would break the project's invariants.
  * anything under external/ (P8 is a read-only, pinned submodule)
  * anything under data/ or artifacts/ (generated by jobs, never hand-edited)
  * splits/*.parquet and results/**/episodes* once committed (frozen manifests are regenerated by
    scripts, never edited)
  * an `import rld` / `from rld` line written anywhere in src/ila/ except src/ila/p8_adapter.py
Exit code 2 blocks the tool call; the stderr text is the reason Claude sees.

PostToolUse (--lint): run ruff on an edited .py file; never blocks.
"""

from __future__ import annotations

import json
import os
import re
import subprocess
import sys
from pathlib import Path

BLOCKED_PREFIXES = ("external/", "data/", "artifacts/")
FROZEN_PATTERNS = (re.compile(r"^splits/.*\.parquet$"),)
RLD_IMPORT = re.compile(r"^\s*(import\s+rld\b|from\s+rld[\s.])", re.MULTILINE)
ADAPTER = "src/ila/p8_adapter.py"


def _relative(path: str) -> str:
    root = Path(os.environ.get("CLAUDE_PROJECT_DIR", os.getcwd())).resolve()
    try:
        return Path(path).resolve().relative_to(root).as_posix()
    except ValueError:
        return Path(path).as_posix()


def _new_text(tool_input: dict) -> str:
    parts = [tool_input.get(k, "") for k in ("content", "new_string")]
    for edit in tool_input.get("edits", []) or []:
        parts.append(edit.get("new_string", ""))
    return "\n".join(p for p in parts if isinstance(p, str))


def pre(event: dict) -> int:
    tool_input = event.get("tool_input", {}) or {}
    path = tool_input.get("file_path") or tool_input.get("notebook_path") or ""
    if not path:
        return 0
    rel = _relative(path)
    if rel.startswith(BLOCKED_PREFIXES):
        print(f"Blocked: {rel} is read-only or job-generated (CLAUDE.md non-negotiable 3 / Style).",
              file=sys.stderr)
        return 2
    if any(p.match(rel) for p in FROZEN_PATTERNS) and Path(path).exists():
        print(f"Blocked: {rel} is a committed manifest; regenerate it with its script and record "
              "the change in docs/protocol.md.", file=sys.stderr)
        return 2
    if rel.startswith("src/ila/") and rel != ADAPTER and RLD_IMPORT.search(_new_text(tool_input)):
        print(f"Blocked: {rel} imports rld. Only {ADAPTER} may import P8 (plan §1.1).",
              file=sys.stderr)
        return 2
    return 0


def post(event: dict) -> int:
    path = (event.get("tool_input", {}) or {}).get("file_path", "")
    if path.endswith(".py"):
        ruff = Path(os.environ.get("CLAUDE_PROJECT_DIR", ".")) / ".venv/bin/ruff"
        if ruff.exists():
            subprocess.run([str(ruff), "check", "--quiet", path], check=False)
    return 0


def main() -> int:
    try:
        event = json.load(sys.stdin)
    except json.JSONDecodeError:
        return 0
    return post(event) if "--lint" in sys.argv[1:] else pre(event)


if __name__ == "__main__":
    sys.exit(main())
